/* Franquia Lab · cópia local e estudos criptografados na nuvem. */
'use strict';
const M=FranquiaModel,KEY='franquia-lab-v1';
const colors=['#347b58','#a88b4c','#8d83b5','#448c9a','#b5715d','#718547'];
const soft=['#edf4e5','#f7f0df','#f1edf9','#e8f4f6','#faeee7','#f0f4e6'];
const money=v=>Number.isFinite(v)?v.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}):'—';
const num=(v,d=1)=>Number.isFinite(v)?v.toLocaleString('pt-BR',{maximumFractionDigits:d}):'—';
const pct=v=>v===null?'—':num(v)+'%';
const pb=(v,h)=>v===null?'Não retorna em '+h+' meses':num(v,2)+' meses';
const e=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
let storageOK=true;
let state={version:1,items:M.seeds(),settings:{horizon:60,tma:12,scenario:'base',budget:100000},selected:'example-a',view:'overview'};
function validSettings(s){return s&&[12,24,36,60,120].includes(s.horizon)&&Number.isFinite(s.tma)&&s.tma>=0&&s.tma<=1000&&Number.isFinite(s.budget)&&s.budget>=0&&Object.hasOwn(M.scenarios,s.scenario)&&(!s.scenarioValues||Object.keys(M.scenarios).every(k=>{const v=s.scenarioValues[k];return v&&Number.isFinite(v.revenue)&&v.revenue>=-100&&v.revenue<=500&&Number.isFinite(v.margin)&&v.margin>=-100&&v.margin<=100;}));}
function parseStudy(data){
  if(data.version!==1||!Array.isArray(data.items)||data.items.length>30||!validSettings(data.settings))throw Error('Formato do estudo inválido.');
  const ids=new Set();
  const items=data.items.map(p=>{if(typeof p.name!=='string'||typeof p.id!=='string'||ids.has(p.id))throw Error('Franquias inválidas ou repetidas.');ids.add(p.id);const item=M.hydrate(p);if(M.validate(item).length)throw Error('Há números inválidos no arquivo.');if(!Array.isArray(item.checked))item.checked=[];return item;});
  const settings={...data.settings};if(!settings.scenarioValues&&data.items.some(p=>!p.analysisMode))settings.scenarioValues=Object.fromEntries(Object.entries(M.scenarios).map(([k,v])=>[k,{revenue:Math.round((v.factor-1)*100),margin:0}]));
  return {version:1,items,settings,selected:items.some(x=>x.id===data.selected)?data.selected:items[0]?.id,view:['overview','editor','cash','research','method'].includes(data.view)?data.view:'overview'};
}
try{const saved=localStorage.getItem(KEY);if(saved)state=parseStudy(JSON.parse(saved));}catch(err){storageOK=false;}
const app=document.getElementById('app');
function current(){return state.items.find(p=>p.id===state.selected)||state.items[0];}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}storageStatus();if(window.cloudStore && !applyingCloud)window.cloudStore.changed();}
function storageStatus(){document.querySelector('.local-status').textContent=storageOK?'● Dados salvos neste navegador':'● Armazenamento indisponível';if(!storageOK&&!document.querySelector('.saving-warning')){const el=document.createElement('div');el.className='saving-warning';el.textContent='Não foi possível salvar os dados. Use Backup para guardar seu estudo antes de fechar.';document.body.append(el);}else if(storageOK)document.querySelector('.saving-warning')?.remove();if(typeof updateCloudBadge === 'function')updateCloudBadge();}
if(typeof updateCloudBadge === "function")updateCloudBadge();
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
const navs=[['overview','◫','Comparar franquias'],['editor','⌘','Premissas e custos'],['cash','↗','Fluxo de caixa'],['research','⌕','Explorar redes'],['method','▤','Como calcular']];
function heading(title,desc,action=true){return `<div class="page-heading"><div><div class="eyebrow">INVESTIR COM CLAREZA</div><h1>${title}</h1><p>${desc}</p></div>${action?'<button class="primary" data-action="new"><span>＋</span> Nova franquia</button>':''}</div>`;}
function scenarioInput(param,label,suffix,min,max){const values=scenarioValues()[state.settings.scenario];return `<label class="scenario-number"><span>${label}</span><div><input aria-label="${label}" data-scenario-param="${param}" type="number" min="${min}" max="${max}" step="any" value="${values[param]}"><b>${suffix}</b></div></label>`;}
function scenarioValues(){return state.settings.scenarioValues||Object.fromEntries(Object.entries(M.scenarios).map(([k,v])=>[k,{revenue:Math.round((v.factor-1)*100),margin:v.marginDelta}]));}
function toolbar(){return `<div class="toolbar scenario-toolbar"><div class="toolbar-group"><span class="label">Cenário</span><div class="segment">${Object.entries(M.scenarios).map(([k,v])=>`<button data-scenario="${k}" class="${state.settings.scenario===k?'active':''}" aria-pressed="${state.settings.scenario===k}">${v.label}</button>`).join('')}</div></div><div class="toolbar-group"><label class="label" for="horizon">Horizonte</label><select class="inline-input" id="horizon" data-setting="horizon">${[12,24,36,60,120].map(n=>`<option value="${n}" ${state.settings.horizon===n?'selected':''}>${n} meses</option>`).join('')}</select><label class="label" for="budget">Meu capital R$</label><input class="inline-input" id="budget" type="number" min="0" step="1000" data-setting="budget" value="${state.settings.budget}"></div><div class="scenario-controls">${scenarioInput('revenue','Variação do faturamento','%',-100,500)}${scenarioInput('margin','Variação da margem','p.p.',-100,100)}<div class="scenario-explainer"><strong>Duas alavancas independentes.</strong><span>+20% nas vendas multiplica a receita por 1,20. +3 p.p. na margem transforma 15% em 18%.</span></div><button class="quiet small" data-action="reset-scenario">Restaurar este cenário</button></div></div>`;}
function selector(){return `<div class="analysis-select"><span class="label">Franquia em análise</span><select id="franchise-select" class="select" aria-label="Franquia em análise">${state.items.map(p=>`<option value="${e(p.id)}" ${current()?.id===p.id?'selected':''}>${e(p.name)}${p.example?' · exemplo':''}</option>`).join('')}</select><span class="subtle">Valores totais da operação cadastrada, por mês.</span></div>`;}
function empty(){return `<div class="empty"><div class="eyebrow">SEU ESTUDO COMEÇA AQUI</div><h2>Qual franquia você quer avaliar?</h2><p>Cadastre uma proposta ou carregue os exemplos para testar a ferramenta.</p><div class="button-row" style="justify-content:center"><button class="primary" data-action="new">＋ Cadastrar franquia</button><button data-action="examples">Carregar exemplos</button></div></div>`;}
function graph(series,{height=225,label='Fluxo de caixa acumulado'}={}){
  if(!series.length)return '';
  const w=690,h=height,l=63,r=15,t=20,b=30;
  const values=series.flatMap(s=>s.values),min=Math.min(0,...values),max=Math.max(1,...values),range=max-min||1;
  const y=v=>t+(max-v)/range*(h-t-b),n=series[0].values.length-1,x=i=>l+(w-l-r)*i/Math.max(1,n);
  let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${e(label)}"><title>${e(label)}</title>`;
  for(let i=0;i<=4;i++){const v=min+range*i/4,yy=y(v);svg+=`<line x1="${l}" y1="${yy}" x2="${w-r}" y2="${yy}" stroke="#e9eee3" stroke-dasharray="3 4"/><text x="${l-10}" y="${yy+3}" text-anchor="end">${v<0?'−':''}${num(Math.abs(v)/1000,0)} mil</text>`;}
  svg+=`<line x1="${l}" y1="${y(0)}" x2="${w-r}" y2="${y(0)}" stroke="#b7c5ab" stroke-dasharray="5 4"/>`;
  for(let i=0;i<=4;i++){const m=Math.round(n*i/4);svg+=`<text x="${x(m)}" y="${h-7}" text-anchor="middle">Mês ${m}</text>`;}
  for(const s of series){const d=s.values.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');svg+=`<path d="${d}" fill="none" stroke="${s.color}" stroke-width="2.5" stroke-linejoin="round"/><circle cx="${x(n)}" cy="${y(s.values[n])}" r="4" fill="${s.color}"/>`;}
  return svg+'</svg>';
}

function investmentTitle(p){return p.investmentStatus==='partial'?'Subtotal de abertura informado':'Investimento total';}
function paybackTitle(p){return p.investmentStatus==='partial'?'Payback sobre subtotal (provisório)':'Payback do investimento total';}
function proposalNotices(p){
 let html='';
 if(p.investmentStatus==='partial')html+=`<div class="notice warning"><strong>Orçamento de abertura incompleto.</strong> ${money(M.investment(p))} é apenas a soma dos itens informados. Valores ainda desconhecidos não foram tratados como custos comprovadamente zerados. Payback e saldos são provisórios e mudarão quando os investimentos faltantes forem incluídos.</div>`;
 if(p.contractMonths>0&&state.settings.horizon>p.contractMonths)html+=`<div class="notice warning"><strong>Horizonte maior que o prazo contratual.</strong> A proposta informa ${p.contractMonths} meses de contrato. A simulação de ${state.settings.horizon} meses pressupõe continuidade/renovação que precisa ser confirmada.</div>`;
 if(p.revenueLow>0||p.revenueHigh>0)html+=`<div class="notice"><strong>Faixa de faturamento referida na proposta:</strong> ${money(p.revenueLow)} a ${money(p.revenueHigh)}/mês. A simulação usa a receita-base editável de ${money(M.revenue(p))}, antes dos ajustes do cenário. Consulte as notas para a origem e as ressalvas.</div>`;
 if(p.notes)html+=`<details class="panel advanced proposal-notes"><summary>Notas, fontes e pendências desta proposta</summary><p style="white-space:pre-wrap;font-size:12px;line-height:1.8">${e(p.notes)}</p></details>`;
 return html;
}

function overview(){
 let html=heading('Quanto investir. Quanto vai sobrar.','Compare o lucro informado pelas redes e descubra quando ele recupera seu investimento.')+toolbar();
 if(!state.items.length)return html+empty();
 const h=state.settings.horizon,results=state.items.map(p=>({p,...M.project(p,state.settings)}));
 if(state.items.some(p=>p.investmentStatus==='partial'))html+='<div class="notice warning"><strong>Há orçamentos parciais na comparação.</strong> Os retornos dessas propostas são provisórios e usam somente os itens de abertura conhecidos.</div>';
 if(state.items.some(p=>p.example))html+=`<div class="notice"><strong>Exemplos fictícios para testar.</strong> Cadastre a margem e o faturamento que cada rede informou. <a href="#editor" data-view="editor">Editar minha proposta ↗</a></div>`;
 if(state.items.some(p=>p.analysisMode==='detailed'))html+=`<div class="notice"><strong>Novo: análise pelo lucro informado.</strong> Suas simulações anteriores foram preservadas no modo detalhado. Em Premissas, escolha “Lucro informado” para avaliar sem preencher os custos mensais.</div>`;
 html+=`<div class="section-title"><h2>Suas alternativas <span class="count">${results.length}</span></h2><div class="button-row">${state.items.some(p=>p.example)?'<button class="quiet remove-demo" data-action="remove-examples">Remover exemplos</button>':''}<button class="quiet small" data-action="print">↗ Imprimir / PDF</button></div></div><div class="cards">${results.map((q,i)=>`<article class="franchise-card" style="--card-color:${colors[i%colors.length]};--card-soft:${soft[i%soft.length]}"><div class="card-top"><span class="monogram">${e(q.p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span class="badge ${q.p.investmentStatus==='partial'||q.equity+q.additional>state.settings.budget?'warn':'good'}">${q.p.investmentStatus==='partial'?'Orçamento parcial':q.equity+q.additional>state.settings.budget?'Acima do seu capital':q.p.analysisMode==='margin'?'Lucro informado':'Custos detalhados'}</span></div><h3>${e(q.p.name)}</h3><div class="card-sub">${e(q.p.format)}${q.p.example?' · Fictício':''}</div><span class="label">${investmentTitle(q.p)}</span><div class="big-number">${money(q.total)}</div><div class="card-divider"><div><span class="subtle">Lucro mensal estimado¹</span><div class="mini-value ${q.stable.projectCash<0?'negative':'positive'}">${money(q.stable.projectCash)}</div></div><div><span class="subtle">${q.p.investmentStatus==='partial'?'Payback sobre subtotal':'Recupera o investimento em'}</span><div class="mini-value">${q.total===0?'Informe o valor':q.projectPayback===null?'>'+h+' meses':num(q.projectPayback,2)+' meses'}</div></div></div><div class="profit-strip"><span>${q.p.investmentStatus==='partial'?'Saldo após o subtotal²':'Saldo após recuperar o investimento²'}</span><strong class="${q.projectEnding<0?'negative':'positive'}">${money(q.projectEnding)}</strong><small>ao final de ${h} meses · antes do financiamento</small></div><div class="card-foot"><span class="badge">${q.p.example?'Exemplo fictício':e(q.p.city)}</span><button class="edit-link" data-edit="${e(q.p.id)}">Editar proposta ↗</button></div></article>`).join('')}</div><p class="scroll-note">¹ No mês de estabilização, após ajustes e antes das parcelas. ² Soma dos lucros mensais menos todo o investimento inicial. Valor negativo indica capital ainda não recuperado.</p>`;
 html+=`<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Quando o lucro paga a abertura?</h2><p>Lucro acumulado menos o investimento total · antes do financiamento</p></div><span class="badge">${h} meses</span></div>${graph(results.map((q,i)=>({color:colors[i%colors.length],values:[-q.total,...q.rows.map(r=>r.projectCumulative)]})),{label:'Lucro acumulado menos investimento total'})}<div class="legend">${results.map((q,i)=>`<span><i class="dot" style="background:${colors[i%colors.length]}"></i>${e(q.p.name)}</span>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Como ler o retorno</h2></div><div class="insights-grid"><div class="insight"><span class="label">LUCRO ≠ FATURAMENTO</span><strong>A margem muda a conta.</strong><p>Faturar R$ 30 mil com margem de 15% gera R$ 4.500. Com margem de 18%, gera R$ 5.400, antes de eventuais deduções adicionais.</p></div><div class="insight orange"><span class="label">ROYALTIES SEM DUPLICIDADE</span><strong>Já estão dentro do lucro?</strong><p>Se a margem informada já considera royalties, eles aparecem como referência e não são descontados novamente.</p></div></div></section></div>`;
 const metrics=[['Modo de análise',q=>q.p.analysisMode==='margin'?'Margem informada':'Custos detalhados'],['Investimento / subtotal',q=>money(q.total)+(q.p.investmentStatus==='partial'?' (parcial)':'')],['Capital próprio inicial',q=>money(q.equity)],['Faturamento estabilizado',q=>money(q.stable.revenue)],['Margem informada pela rede',q=>q.p.analysisMode==='margin'?pct(q.p.advertisedMargin):'—'],['Margem aplicada no cenário³',q=>q.p.analysisMode==='margin'?pct(q.stable.scenarioMargin):'Ajuste sobre o CMV'],['Royalties mensais (referência)',q=>money(q.stable.royaltyReference??q.stable.royalties)],['Royalties já inclusos na margem?',q=>q.p.analysisMode==='margin'?(q.p.royaltiesIncluded==='yes'?'Sim':'Não · descontados à parte'):'Custos apurados'],['Lucro mensal após ajustes¹',q=>money(q.stable.projectCash)],['Lucro acumulado no período',q=>money(q.totalProfit)],['Saldo após o investimento²',q=>money(q.projectEnding)],['Payback total ou provisório',q=>(q.total===0?'Informe o investimento':pb(q.projectPayback,h))+(q.p.investmentStatus==='partial'?' · parcial':'')],['Parcela do financiamento',q=>money(q.installment)],['Caixa mensal após parcela',q=>money(q.stable.cash)],['Payback do capital próprio',q=>q.equity===0?'Sem aporte':pb(q.payback,h)],['Saldo do investidor após aporte',q=>money(q.ending)],['VPL do capital próprio',q=>money(q.npv)],['Aporte além do giro',q=>money(q.additional)]];
 html+=`<section class="panel comparison-panel"><div class="panel-head"><div><h2>A comparação completa</h2><p>${M.scenarios[state.settings.scenario].label} · ${h} meses · TMA ${num(state.settings.tma)}% ao ano</p></div><button class="quiet small" data-action="csv">↓ Exportar CSV</button></div><div class="table-wrap"><table><thead><tr><th>INDICADOR</th>${results.map(q=>`<th>${e(q.p.name)}</th>`).join('')}</tr></thead><tbody>${metrics.map(([label,fn])=>`<tr><td class="metric">${label}</td>${results.map(q=>`<td>${fn(q)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><p class="scroll-note">³ Margem do anúncio + variação em pontos percentuais, antes de royalties não inclusos e despesas extras. Projeções condicionadas às informações das redes, sem validação independente dos lucros.</p>`;
 if(results.some(q=>q.loan>0&&q.p.term>h))html+='<div class="notice warning">Existe financiamento com parcelas fora do horizonte. O VPL não inclui essas parcelas futuras nem deduz o saldo devedor terminal; amplie o período antes de comparar o retorno do investidor.</div>';
 return html;
}
function field(label,key,{type='number',hint='',options=null,min=0,max='',step='any',full=false}={}){
  const p=current();return `<label class="field ${full?'full':''}"><span>${label}</span>${options?`<select data-field="${key}" id="field-${key}">${options.map(([v,t])=>`<option value="${v}" ${p[key]===v?'selected':''}>${t}</option>`).join('')}</select>`:type==='textarea'?`<textarea data-field="${key}" id="field-${key}">${e(p[key])}</textarea>`:`<input id="field-${key}" data-field="${key}" type="${type}" value="${e(p[key])}" ${type==='number'?`min="${min}" ${max!==''?`max="${max}"`:''} step="${step}"`:''} ${type==='text'?'maxlength="500"':''}>`}${hint?`<small>${hint}</small>`:''}</label>`;
}
function formPanel(n,title,desc,content){return `<section class="panel form-panel"><div class="panel-head"><div><h2><span class="step-number">${n}</span>${title}</h2><p>${desc}</p></div></div><div class="fields">${content}</div></section>`;}
function modeChoice(){const p=current();return `<section class="mode-choice"><div><span class="eyebrow">COMO VOCÊ QUER FAZER A CONTA?</span><h2>Comece com o que a rede informa.</h2></div><div class="mode-options"><button data-mode="margin" aria-pressed="${p.analysisMode==='margin'}" class="${p.analysisMode==='margin'?'selected':''}"><strong>Lucro informado</strong><span>Faturamento + margem + royalties</span></button><button data-mode="detailed" aria-pressed="${p.analysisMode==='detailed'}" class="${p.analysisMode==='detailed'?'selected':''}"><strong>Custos detalhados</strong><span>Para quando você conhecer a operação</span></button></div></section>`;}
function summary(){
 const p=current(),q=M.project(p,state.settings),r=q.stable;
 return `<div class="summary-title">Quanto sobra na sua proposta?</div><span class="badge">${M.scenarios[state.settings.scenario].label} · ${state.settings.horizon} meses</span><div class="label" style="margin-top:20px">Lucro mensal estimado¹</div><div class="summary-total ${r.projectCash<0?'negative':'positive'}">${money(r.projectCash)}</div>${[['Faturamento',money(r.revenue)],...(p.analysisMode==='margin'?[['Margem do cenário',pct(r.scenarioMargin)],['Lucro pela margem',money(r.reportedProfit)],['Royalties a descontar',money(r.royalties)],['Extras fora da margem',money(p.marginExtra)]]:[]),[investmentTitle(p),money(q.total)],[paybackTitle(p),q.total===0?'Informe o investimento':pb(q.projectPayback,state.settings.horizon)],['Lucro acumulado',money(q.totalProfit)],['Saldo após investimento',money(q.projectEnding)],...(q.loan>0?[['Parcela',money(q.installment)],['Caixa após parcela',money(r.cash)],['Payback do seu aporte',q.equity===0?'Sem aporte':pb(q.payback,state.settings.horizon)]]:[])].map(([k,v])=>`<div class="readout"><span>${k}</span><strong>${v}</strong></div>`).join('')}<p class="summary-note">¹ No mês ${r.month}, antes de parcelas. O saldo desconta o investimento total do lucro acumulado. Valores salvos enquanto você edita.</p>${p.investmentStatus==='partial'?'<p class="summary-note negative"><strong>Orçamento parcial: o payback não representa o investimento completo.</strong></p>':''}${p.analysisMode==='margin'?`<p class="summary-note">Royalties de referência: ${money(r.royaltyReference)}/mês. ${p.royaltiesIncluded==='yes'?'Já inclusos: sem nova dedução.':'Descontados do lucro informado.'} Custos detalhados não entram neste modo.</p>`:''}<div class="summary-actions"><button class="primary small" data-view="cash">Ver retorno mês a mês ↗</button><button class="small" data-action="duplicate">Duplicar proposta</button><button class="small danger" data-action="delete">Excluir franquia</button></div>`;
}
function detailedEditor(){
  let html=heading('As premissas fazem a diferença.','Edite os números da proposta. O resultado acompanha cada alteração.')+toolbar();
  if(!current())return html+empty();
  const p=current();html+=selector()+modeChoice()+proposalNotices(p)+`<div class="editor-grid"><div class="forms">`;
  html+=formPanel('01','A proposta','Use o mesmo escopo em todos os campos: uma loja ou a operação inteira.',field('Nome da franquia','name',{type:'text'})+field('Cidade / região','city',{type:'text'})+field('Formato e quantidade de pontos','format',{type:'text',hint:'Ex.: Autônomo · 2 pontos. Os valores abaixo devem somar os 2 pontos.'})+field('Fonte / link da proposta','source',{type:'text'})+field('Observações e pendências','notes',{type:'textarea',full:true}));
  html+=formPanel('02','Investimento para abrir','Valores pagos uma vez, antes da operação. Não repita itens inclusos no pacote.',[['Taxa de franquia · R$','fee'],['Obra / montagem · R$','setup'],['Equipamentos e tecnologia · R$','equipment'],['Estoque inicial · R$','stock'],['Licenças, treinamento e pré-abertura · R$','preopen'],['Capital de giro reservado · R$','working']].map(([a,b])=>field(a,b)).join('')+field('Contingência da implantação · %','contingency',{max:100,hint:'Sobre taxa + montagem + equipamentos + estoque + pré-abertura. Não incide sobre capital de giro.'}));
  html+=formPanel('03','Receita e ritmo de abertura','A receita cresce linearmente até o mês de estabilização.',field('Como estimar o faturamento?','revenueMode',{options:[['direct','Informar faturamento mensal'],['ticket','Ticket médio × vendas por dia']]})+(p.revenueMode==='direct'?field('Faturamento mensal estabilizado · R$','revenue'):field('Ticket médio · R$','ticket')+field('Vendas / transações por dia','salesDay')+field('Dias de operação por mês','days',{max:31}))+field('Estabilização no mês','ramp',{min:1,max:120,step:1})+field('Receita no primeiro mês · % da meta','start',{max:100})+field('Crescimento anual após estabilizar · %','growth',{min:-99,max:200,hint:'Taxa efetiva, aplicada mês a mês após a rampa.'})+field('Reajuste anual dos custos fixos · %','inflation',{min:-99,max:100}));
  html+=formPanel('04','Custos que acompanham as vendas','Percentuais sobre faturamento bruto, exceto se mudar a base dos royalties.',field('Custo da mercadoria vendida (CMV) · %','cmv',{max:100,hint:'Custo de compra da mercadoria vendida. Margem bruta = 100% − CMV.'})+field('Impostos sobre faturamento · %','tax',{max:100,hint:'Alíquota efetiva estimada; ajuste com seu contador.'})+field('Cartão / meios de pagamento · %','payment',{max:100})+field('Perdas, furtos e vencimento · %','loss',{max:100,hint:'Adicional ao CMV. Se o CMV já incluir perdas, use zero aqui.'})+field('Repasse ao condomínio / ponto · %','condo',{max:100})+field('Fundo de propaganda · %','marketing',{max:100})+field('Propaganda fixa adicional · R$/mês','marketingFixed')+field('Formato de royalties','royaltyMode',{options:[['percent','Percentual'],['fixed','Valor fixo'],['minimum','Percentual com mínimo mensal']]})+field('Base do percentual de royalties','royaltyBase',{options:[['revenue','Faturamento bruto'],['cmv','Compras (aproximadas pelo CMV)']]})+field('Royalties · %','royalty',{max:100})+field('Royalties fixos ou mínimo · R$/mês','royaltyFixed',{hint:'Aplicado apenas no modo fixo ou mínimo. No modo percentual é ignorado.'}));
  html+=formPanel('05','Custos mensais de operação','Considere o custo do seu trabalho, mesmo sem funcionários.',[['Aluguel / condomínio fixo · R$','rent'],['Equipe + encargos · R$','payroll'],['Pró-labore do dono · R$','owner'],['Energia, água e internet · R$','utilities'],['Sistema / software · R$','software'],['Contabilidade · R$','accounting'],['Reposição / combustível / logística · R$','logistics'],['Outros custos fixos · R$','other'],['Reserva mensal de manutenção · R$','maintenance']].map(([a,b])=>field(a,b)).join('')+`<div class="full field"><span>Custos adicionais personalizados</span><div id="extra-list">${p.extra.map((x,i)=>`<div class="extra-row"><input aria-label="Descrição do custo ${i+1}" data-extra="${i}" data-prop="name" value="${e(x.name)}" placeholder="Ex.: seguro"><input aria-label="Valor do custo ${i+1}" type="number" min="0" step="any" data-extra="${i}" data-prop="value" value="${x.value}"><select aria-label="Tipo do custo ${i+1}" data-extra="${i}" data-prop="type"><option value="fixed" ${x.type==='fixed'?'selected':''}>R$/mês</option><option value="percent" ${x.type==='percent'?'selected':''}>% receita</option></select><button data-remove-extra="${i}" aria-label="Remover custo ${i+1}">×</button></div>`).join('')}</div><button class="small" data-action="add-cost">＋ Adicionar custo</button></div>`);
  html+=formPanel('06','Capital e financiamento','Financiamento opcional. Sistema Price, sem carência, com primeira parcela no mês 1.',field('Valor financiado · R$','loan',{max:M.investment(p),hint:'Reduz o aporte inicial. Não pode ultrapassar o investimento total.'})+field('Custo efetivo do crédito · % ao ano','interest',{max:1000,hint:'Informe o custo efetivo total, incluindo encargos.'})+field('Quantidade de parcelas','term',{min:1,max:360,step:1})+`<div class="field"><span>Parcela estimada</span><div id="loan-installment" class="summary-total" style="font-size:21px">${money(M.project(p,state.settings).installment)}</div></div>`);
  html+=`</div><aside class="panel sticky" id="live-summary">${summary()}</aside></div>`;
  return html;
}
function simpleEditor(){
 let html=heading('Da proposta ao retorno.','Use a margem de lucro que a franqueadora apresenta. Os custos desconhecidos não precisam ser preenchidos.')+toolbar();
 if(!current())return html+empty();
 const p=current();html+=selector()+modeChoice()+proposalNotices(p)+`<div class="editor-grid"><div class="forms">`;
 html+=formPanel('01','O lucro que a rede informa','Margem é o percentual do faturamento que sobra como lucro; não é retorno percentual sobre o capital.',field('Nome da franquia','name',{type:'text'})+field('Cidade / região','city',{type:'text'})+(p.revenueMode==='direct'?field('Faturamento mensal esperado · R$','revenue'):field('Ticket médio · R$','ticket')+field('Vendas por dia','salesDay')+field('Dias de operação por mês','days',{max:31}))+field('Margem de lucro informada · % do faturamento','advertisedMargin',{max:100,hint:'Ex.: 15 significa R$ 15 de lucro para cada R$ 100 vendidos, após os custos que a rede diz já incluir.'})+(p.royaltyMode==='fixed'?field('Royalties fixos · R$/mês','royaltyFixed'):field('Royalties · % do faturamento','royalty',{max:100}))+field('A margem informada já desconta royalties?','royaltiesIncluded',{options:[['yes','Sim · não descontar outra vez'],['no','Não · descontar os royalties à parte']]})+`<div class="full notice" style="margin-bottom:0">Confirme se a margem apresentada já inclui impostos, perdas, pró-labore e taxas. Aqui ela é tratada como lucro operacional disponível em caixa, antes do financiamento. Use “extras fora da margem” apenas para o que ficou de fora.</div>`);
 html+=formPanel('02','Tudo o que você investe para abrir','O lucro precisa recuperar todo o investimento, não apenas a taxa de franquia.',field('O orçamento de abertura está completo?','investmentStatus',{options:[['complete','Completo · todos os itens incluídos'],['partial','Parcial · ainda faltam valores']]})+field('Como informar o investimento?','investmentMode',{options:[['items','Somar taxa, montagem, estoque e giro'],['total','Informar um valor total fechado']]})+(p.investmentMode==='total'?field('Investimento total da proposta · R$','investmentTotal',{hint:'Já deve incluir taxa, montagem, equipamentos, estoque, contingência e giro. Não somamos os itens novamente.'})+field('Giro dentro desse total · R$','working',{max:p.investmentTotal,hint:'Informação para acompanhar o caixa. Está dentro do total acima e não é somado outra vez.'}):field('Taxa de franquia · R$','fee')+field('Montagem / implantação · R$','setup')+field('Equipamentos · R$','equipment')+field('Estoque inicial · R$','stock')+field('Pré-abertura e outros investimentos · R$','preopen')+field('Capital de giro reservado · R$','working')+field('Contingência da implantação · %','contingency',{max:100,hint:'Sobre os itens de abertura; não incide sobre o giro.'})));
 html+=`<details class="panel advanced"><summary>Ajustes opcionais: crescimento, extras e financiamento</summary><p class="subtle">Se não houver crescimento inicial, mantenha estabilização no mês 1. Os campos detalhados de operação são ignorados neste modo.</p><div class="fields">${field('Extras mensais fora da margem · R$','marginExtra',{hint:'Só despesas ainda não incluídas no lucro informado. Ex.: seu pró-labore, se a rede não o considerar.'})+field('Crescimento anual do faturamento · %','growth',{min:-99,max:200,hint:'Aplicado mensalmente depois da estabilização.'})+field('Estabilização no mês','ramp',{min:1,max:120,step:1})+field('Receita no primeiro mês · % da meta','start',{max:100})+field('Como estimar o faturamento?','revenueMode',{options:[['direct','Informar faturamento mensal'],['ticket','Ticket × vendas por dia']]})+field('Formato de royalties','royaltyMode',{options:[['percent','Percentual'],['fixed','Valor fixo'],['minimum','Percentual com mínimo mensal']]})+(p.royaltyMode==='fixed'?'':field('Royalty fixo ou mínimo · R$/mês','royaltyFixed'))+field('Valor financiado · R$','loan',{max:M.investment(p)})+field('Custo efetivo do crédito · % ao ano','interest',{max:1000})+field('Quantidade de parcelas','term',{min:1,max:360,step:1})}</div><p class="scroll-note">Royalties percentuais usam faturamento bruto no modo simples. As parcelas reduzem o caixa do investidor; o payback total usa o lucro antes das parcelas e o payback do capital próprio considera a dívida.</p></details>`;
 html+=`<details class="panel advanced"><summary>Fonte, formato e observações</summary><div class="fields" style="margin-top:18px">${field('Formato e quantidade de pontos','format',{type:'text'})+field('Prazo contratual informado · meses','contractMonths',{min:0,max:600,step:1,hint:'Zero significa não informado. Não limita automaticamente a simulação.'})+field('Faixa de receita informada: mínimo · R$','revenueLow')+field('Faixa de receita informada: máximo · R$','revenueHigh')+field('Fonte / link da proposta','source',{type:'text'})+field('Observações e pendências','notes',{type:'textarea',full:true})}</div></details></div><aside class="panel sticky" id="live-summary">${summary()}</aside></div>`;
 return html;
}
function editor(){return !current()||current().analysisMode==='margin'?simpleEditor():detailedEditor();}
function sensitivity(p){
 return `<div class="section-title"><div><h2>E se as vendas e a margem mudarem?</h2><p>Payback do investimento total · cada célula é uma combinação independente</p></div></div><section class="panel"><div class="table-wrap"><table class="heatmap"><thead><tr><th>${p.analysisMode==='margin'?'Margem informada':'Margem bruta'} ↓ / Faturamento →</th>${[-20,-10,0,10,20].map(x=>`<th>${x>0?'+':''}${x}%</th>`).join('')}</tr></thead><tbody>${[-3,0,3].map(d=>`<tr><th>${num(Math.min(100,Math.max(-100,(p.analysisMode==='margin'?p.advertisedMargin:100-p.cmv)+d)))}%</th>${[-20,-10,0,10,20].map(v=>{const q=M.project(p,state.settings,{factor:1+v/100,marginDelta:d});return `<td class="${q.projectPayback!==null&&q.projectPayback<=24?'good':q.projectPayback===null?'bad':'mid'}">${q.total===0?'Sem investimento':q.projectPayback===null?'>'+state.settings.horizon+' meses':num(q.projectPayback,2)+' meses'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="scroll-note">Base: faturamento e margem da proposta, sem os ajustes do cenário selecionado. A margem varia em −3 / 0 / +3 pontos percentuais. Royalties não inclusos e extras são descontados em cada cálculo. No modo detalhado, variar a margem bruta ajusta o CMV.</p></section>`;
}
function cash(){
 let html=heading('Quando o lucro paga o investimento?','Veja quanto entra de lucro, quanto falta recuperar e o saldo depois de pagar a abertura.',false)+toolbar();
 if(!current())return html+empty();
 const p=current(),q=M.project(p,state.settings),h=state.settings.horizon;
 html+=selector()+proposalNotices(p)+`<div class="kpi-grid profit-kpis">${[['Lucro mensal estabilizado',money(q.stable.projectCash),'Antes do financiamento · mês '+q.stable.month],[paybackTitle(p),q.total===0?'Informe o investimento':q.projectPayback===null?'>'+h+' meses':num(q.projectPayback,2)+' meses',(p.investmentStatus==='partial'?'Somente o subtotal de ':'Todo o investimento de ')+money(q.total)],['Lucro acumulado em '+h+' meses',money(q.totalProfit),'Soma dos lucros; antes de abater a abertura'],['Saldo após o investimento',money(q.projectEnding),q.projectEnding>=0?'Lucro que excede o investimento inicial':'Valor negativo: investimento ainda não recuperado']].map(([a,b,c])=>`<div class="panel"><div class="label">${a}</div><div class="kpi-value">${b}</div><p>${c}</p></div>`).join('')}</div>`;
 if(q.total===0)html+='<div class="notice warning">Preencha o investimento total para calcular o prazo de recuperação.</div>';
 if(p.analysisMode==='margin')html+=`<div class="notice"><strong>Como o lucro foi estimado:</strong> ${money(q.stable.revenue)} × ${pct(q.stable.scenarioMargin)} = ${money(q.stable.reportedProfit)}. ${p.royaltiesIncluded==='yes'?`Royalties de ${money(q.stable.royaltyReference)} já estão inclusos; sem nova dedução.`:`Menos ${money(q.stable.royalties)} de royalties.`} ${p.marginExtra>0?'Menos '+money(p.marginExtra)+' de extras fora da margem.':''} Lucro ajustado: <strong>${money(q.stable.projectCash)}/mês</strong>. A precisão depende da margem informada, que não foi auditada.</div>`;
 const scenarioRows=Object.keys(M.scenarios).map(key=>({key,...M.project(p,{...state.settings,scenario:key})}));
 html+=`<section class="panel"><div class="panel-head"><div><h2>Compare os três cenários da proposta</h2><p>Vendas e margem podem variar juntas ou separadamente. Edite os ajustes na barra acima.</p></div></div><div class="table-wrap"><table><thead><tr><th>Cenário</th><th>Vendas</th><th>Margem Δ</th><th>Lucro / mês¹</th><th>${p.investmentStatus==='partial'?'Payback provisório':'Payback total'}</th><th>Lucro acumulado</th><th>Saldo após investimento</th></tr></thead><tbody>${scenarioRows.map(s=>{const v=scenarioValues()[s.key];return `<tr><td><i class="dot" style="background:${{pessimistic:colors[1],base:colors[0],optimistic:colors[2]}[s.key]}"></i>${M.scenarios[s.key].label}</td><td>${v.revenue>0?'+':''}${num(v.revenue)}%</td><td>${v.margin>0?'+':''}${num(v.margin)} p.p.</td><td>${money(s.stable.projectCash)}</td><td>${s.total===0?'Informe o valor':pb(s.projectPayback,h)}</td><td>${money(s.totalProfit)}</td><td class="${s.projectEnding<0?'negative':'positive'}">${money(s.projectEnding)}</td></tr>`;}).join('')}</tbody></table></div>${graph(scenarioRows.map(s=>({color:{pessimistic:colors[1],base:colors[0],optimistic:colors[2]}[s.key],values:[-s.total,...s.rows.map(r=>r.projectCumulative)]})),{label:'Saldo após investimento total em cada cenário'})}<p class="scroll-note">¹ No mês de estabilização. Gráfico e tabela antes das parcelas do financiamento.</p></section>`;
 html+=sensitivity(p);
 if(q.loan>0)html+=`<section class="panel" style="margin-top:20px"><h2>O seu aporte e o financiamento</h2><div class="kpi-grid" style="margin:18px 0 0">${[['Seu aporte inicial',money(q.equity)],['Parcela Price',money(q.installment)],['Caixa mensal após parcela',money(q.stable.cash)],['Payback do seu aporte',q.equity===0?'Sem aporte':pb(q.payback,h)]].map(([a,b])=>`<div><span class="label">${a}</span><div class="kpi-value">${b}</div></div>`).join('')}</div><p class="scroll-note">VPL do seu aporte: ${money(q.npv)}. Saldo após recuperar seu aporte: ${money(q.ending)}. ${p.term>h?'Atenção: restam '+money(q.rows.at(-1).balance)+' de dívida ao final; parcelas após o horizonte não entram no VPL.':''}</p></section>`;
 if(q.additional>0)html+=`<div class="notice warning" style="margin-top:20px"><strong>Giro insuficiente:</strong> faltariam ${money(q.additional)} no pior mês. Revise a reserva; o aporte adicional não é injetado automaticamente nos cálculos.</div>`;
 html+=`<div class="section-title"><div><h2>O lucro, mês a mês</h2><p>O mês 0 registra ${money(q.total)} de investimento. Saldo = lucro acumulado − investimento total.</p></div><button class="small" data-action="cash-csv">↓ Exportar fluxo CSV</button></div><section class="panel" style="padding:0"><div class="table-wrap cash-table"><table><thead><tr>${['Mês','Faturamento','Royalties¹','Lucro ajustado²','Lucro acumulado','Saldo após investimento','Ainda falta recuperar','Parcelas','Caixa após parcela'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody><tr><td>0 · abertura</td><td>—</td><td>—</td><td>—</td><td>${money(0)}</td><td>${money(-q.total)}</td><td>${money(q.total)}</td><td>—</td><td>${money(-q.equity)}</td></tr>${q.rows.map(r=>`<tr><td>${r.month}</td><td>${money(r.revenue)}</td><td>${money(r.royaltyReference??r.royalties)}</td><td class="${r.projectCash<0?'negative':'positive'}">${money(r.projectCash)}</td><td>${money(r.projectCumulative+q.total)}</td><td class="${r.projectCumulative<0?'negative':'positive'}">${money(r.projectCumulative)}</td><td>${money(Math.max(0,-r.projectCumulative))}</td><td>${money(r.debt)}</td><td>${money(r.cash)}</td></tr>`).join('')}</tbody></table></div></section><p class="scroll-note">¹ No modo por margem, royalties já inclusos são apenas informativos. ² Após royalties não inclusos e extras; no modo detalhado, após custos e manutenção. O lucro é usado como aproximação de caixa. Sem recebíveis a prazo, reinvestimento automático, recuperação final de giro ou venda de ativos.</p>`;
 return html;
}
const networks=[
  {name:'market4u',value:'A partir de R$ 80 mil',type:'Investimento inicial anunciado',desc:'A rede informa que o valor inclui taxa de franquia e implantação da primeira loja. Solicite a composição por item e as condições para São Paulo.',url:'https://market4u.com.br/operacao-24h-sem-funcionario/',source:'Site da franqueadora'},
  {name:'Honest Market Brasil',value:'R$ 45 mil a R$ 90 mil',type:'Investimento total no cadastro ABF',desc:'A ficha informa taxa de R$ 30–40 mil e giro de R$ 15–50 mil; royalties de 6,5% do faturamento. Há divergência com o FAQ da própria ficha: confirme a proposta atual.',url:'https://franquias.portaldofranchising.com.br/franquia-honest-market-brasil/?ri=300001%2C400000',source:'Portal do Franchising · dados da rede'},
  {name:'Be Honest',value:'A partir de R$ 60 mil',type:'Investimento anunciado',desc:'A página informa um valor mínimo, sujeito ao modelo escolhido. Confirme atendimento em São Paulo, custos de implantação, abastecimento e taxas recorrentes.',url:'https://behonestbrasil.com.br/fazer-negocio-escalavel-go/',source:'Site da franqueadora'}
];
const checks=['Recebi uma proposta com taxa, montagem, equipamentos e estoque discriminados.','Confirmei a disponibilidade da marca e de pontos em São Paulo.','Validei vendas e custos com franqueados em operações comparáveis.','Incluí pró-labore, logística de reposição, perdas e capital de giro.','Revisei royalties mínimos, base de cálculo, renovação e saída do contrato.','Revisei a COF e o contrato com profissionais de confiança.'];
function research(){return heading('Um ponto de partida para pesquisar.','Redes de mercados autônomos com informações públicas. Traga a proposta real para o seu estudo.')+`<div class="notice"><strong>Referências consultadas em 26/10/2026.</strong> Valores anunciados podem mudar e não comprovam disponibilidade em São Paulo. Este é um recorte inicial, não um catálogo completo. As projeções de retorno anunciadas não foram usadas no simulador.</div><div class="source-grid">${networks.map((n,i)=>`<article class="panel source-card"><div class="eyebrow">MERCADOS AUTÔNOMOS</div><h2>${n.name}</h2><div class="source-value">${n.value}</div><span class="subtle">${n.type}</span><p>${n.desc}</p><span class="badge">${n.source}</span><a href="${n.url}" target="_blank" rel="noopener noreferrer">Consultar a fonte ↗</a><button class="small" data-network="${i}">＋ Cadastrar proposta desta rede</button></article>`).join('')}</div><div class="section-title"><h2>Antes de colocar uma marca na sua lista</h2></div><section class="panel"><div class="method-grid"><div><h3>Compare o mesmo tipo de operação</h3><p>Uma taxa que permite abrir vários pontos não equivale ao investimento para montar todos eles. Cadastre o número de pontos no formato e some receitas e custos do mesmo conjunto.</p><p>Ao cadastrar uma rede por esta aba, os valores começam zerados para você preencher com a proposta. Os valores anunciados ficam apenas nas observações.</p></div><div><h3>Perguntas para a conversa comercial</h3><ul><li>O investimento anunciado inclui estoque, equipamentos e giro?</li><li>Quem prospecta os pontos e quem assume o custo de reposição?</li><li>Qual o CMV real, as perdas e o repasse ao condomínio?</li><li>Existe mínimo de royalties ou obrigação de comprar de fornecedor específico?</li></ul></div></div></section>`;}
function method(){return heading('A conta do lucro ao retorno.','As fórmulas ficam abertas para você entender de onde vem cada resultado.',false)+`<section class="panel" style="margin-bottom:20px"><div class="fields"><label class="field"><span>Taxa mínima de atratividade · % ao ano</span><input data-setting="tma" type="number" min="0" max="1000" step="any" value="${state.settings.tma}"><small>Usada no VPL e no payback descontado do capital próprio.</small></label><div><h3>Lucro do negócio e retorno do investidor</h3><p class="subtle">O payback total compara todo o investimento com o lucro antes da dívida. Havendo financiamento, o payback do seu aporte usa capital próprio e caixa após parcelas.</p></div></div></section><div class="method-grid">${[
 ['1. Lucro informado pela rede','<div class="formula">Lucro pela margem = faturamento × margem informada / 100<br>Lucro ajustado = lucro pela margem − royalties não inclusos − extras fora da margem</div><p>A margem deve ser sobre faturamento, após os custos que a rede afirma considerar e antes de financiamento. Se os royalties já estiverem nela, não são descontados de novo. O modo simples ignora os campos de custos detalhados, inclusive a manutenção do modo detalhado.</p>'],
 ['2. O que cada cenário muda','<div class="formula">Receita do cenário = receita base × (1 + variação % / 100)<br>Margem do cenário = margem informada + variação em pontos percentuais</div><p>Ex.: margem de 15% + 3 p.p. = 18%, e não 15,45%. Margens são limitadas a −100% e 100%. No modo detalhado, a variação da margem altera o CMV em pontos percentuais, entre 0% e 100%; a margem líquida resultante depende dos demais custos.</p>'],
 ['3. Como o payback é encontrado','<div class="formula">Saldo no mês 0 = −investimento total<br>Saldo no mês m = saldo anterior + lucro ajustado do mês<br>Payback = primeiro mês em que o saldo atinge zero</div><p>Interpolamos a fração do mês. Com lucro constante de R$ 5 mil e investimento de R$ 80 mil, o payback é de 16 meses. Com rampa ou crescimento, a conta soma os lucros reais de cada mês projetado. Lucro zero ou negativo não produz recuperação artificial.</p>'],
 ['4. Quanto você terá de lucro','<div class="formula">Lucro acumulado = soma dos lucros mensais antes das parcelas<br>Saldo após investimento = lucro acumulado − investimento total</div><p>Ex.: R$ 5 mil/mês por 24 meses gera R$ 120 mil de lucro acumulado. Para um investimento de R$ 80 mil, o saldo após recuperar a abertura é R$ 40 mil. São valores antes do financiamento; não somamos o investimento ao lucro novamente.</p>'],
 ['5. Investimento, giro e financiamento','<p>Você pode informar um total fechado ou somar os itens de abertura. No total fechado, o giro informado está dentro do total e não é adicionado de novo. Na soma por itens, a contingência incide sobre abertura, sem o giro.</p><p>Price usa a taxa efetiva anual convertida para mensal. O capital próprio é o total menos a dívida. As parcelas reduzem o caixa do investidor. O VPL usa esse caixa e não presume valor residual dos ativos nem quitação terminal do saldo devedor. Amplie o horizonte para abranger todas as parcelas.</p>'],
 ['6. O que a margem não revela','<p>Esta é uma análise com as hipóteses da proposta, não uma auditoria da rentabilidade da rede. Confirme se a margem inclui impostos, perdas, pró-labore, manutenção, logística e propaganda.</p><p>Sem conhecer a estrutura dos custos, não é possível estimar um ponto de equilíbrio operacional confiável. Por isso, o modo simples não o apresenta. O lucro informado aproxima o caixa, com recebimentos e pagamentos no mesmo mês; não há sazonalidade, expansão ou reinvestimento automáticos.</p>']
 ].map(([a,b])=>`<section class="panel"><h3>${a}</h3>${b}</section>`).join('')}</div><div class="section-title"><h2>Checklist ${current()?'· '+e(current().name):''}</h2></div><section class="panel check-list">${current()?checks.map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${current().checked.includes(i)?'checked':''}>${s}</label>`).join(''):'Cadastre uma proposta.'}</section><p class="scroll-note">Referência: <a target="_blank" rel="noopener noreferrer" href="https://sebrae.com.br/sites/PortalSebrae/ufs/ap/artigos/saiba-como-funciona-o-indicador-de-lucratividade%2C23abcc19e6223610VgnVCM1000004c00210aRCRD">Sebrae · indicador de lucratividade</a>. As regras específicas deste simulador estão descritas acima.</p>`;}
function render(){
  document.getElementById('nav').innerHTML=navs.map(([key,icon,title])=>`<button data-view="${key}" class="${state.view===key?'active':''}" title="${title}" aria-label="${title}" ${state.view===key?'aria-current="page"':''}><span>${icon}</span>${title}</button>`).join('');
  app.innerHTML=({overview,editor,cash,research,method}[state.view]||overview)();
  const toolbarEl=app.querySelector('.toolbar');
  if(toolbarEl){const body=document.createElement('div');body.id='analysis-content';while(toolbarEl.nextSibling)body.append(toolbarEl.nextSibling);app.append(body);}
  storageStatus();
}
function refreshNumericalResults(){
 if(state.view==='editor'){const panel=document.getElementById('live-summary');if(panel){panel.innerHTML=summary();const installmentEl=document.getElementById("loan-installment");if(installmentEl)installmentEl.textContent=money(M.project(current(),state.settings).installment);}return;}
 if(!['overview','cash'].includes(state.view))return;
 const container=document.getElementById('analysis-content');if(!container)return;
 const temp=document.createElement('div');temp.innerHTML=state.view==='overview'?overview():cash();
 const toolbarEl=temp.querySelector('.toolbar'),fragment=document.createDocumentFragment();
 while(toolbarEl?.nextSibling)fragment.append(toolbarEl.nextSibling);
 container.replaceChildren(fragment);
}
function move(view){state.view=view;save();render();window.scrollTo({top:0,behavior:'instant'});}
function add(p={}){if(state.items.length>=30)return toast('Limite de 30 propostas por estudo.');const item=M.make(p);state.items.push(item);state.selected=item.id;move('editor');toast('Proposta criada. Preencha os valores.');}
function ask(title,msg,action){document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-message').textContent=msg;const d=document.getElementById('confirm-dialog');d.showModal();document.getElementById('accept-dialog').onclick=()=>{d.close();action();};document.getElementById('cancel-dialog').onclick=()=>d.close();}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"';}
function exportCSV(flow=false){
 if(!current())return toast('Cadastre uma proposta primeiro.');
 const n=v=>Number.isFinite(v)?v.toFixed(2).replace('.',','):'';
 let rows;
 if(flow){const p=current(),q=M.project(p,state.settings);rows=[['Franquia',p.name,'Cenário',M.scenarios[state.settings.scenario].label,'Modo',p.analysisMode],['Variação receita %',scenarioValues()[state.settings.scenario].revenue,'Variação margem p.p.',scenarioValues()[state.settings.scenario].margin,'Royalties inclusos',p.royaltiesIncluded],['Mês','Receita','Royalties referência','Royalties descontados à parte','Lucro antes de dívida','Lucro acumulado','Saldo após investimento total','Falta recuperar','Parcela','Caixa após parcela','Acumulado investidor','Caixa disponível','Saldo devedor'],[0,0,0,0,0,0,n(-q.total),n(q.total),0,n(-q.equity),n(-q.equity),n(p.working),n(q.loan)],...q.rows.map(r=>[r.month,n(r.revenue),n(r.royaltyReference??r.royalties),n(r.royalties),n(r.projectCash),n(r.projectCumulative+q.total),n(r.projectCumulative),n(Math.max(0,-r.projectCumulative)),n(r.debt),n(r.cash),n(r.cumulative),n(r.liquidity),n(r.balance)])];}
 else rows=[['Franquia','Modo','Orçamento','Cenário','Variação receita %','Variação margem p.p.','Horizonte meses','Investimento total','Capital próprio','Margem informada %','Margem cenário %','Royalties inclusos','Lucro mensal','Lucro acumulado','Saldo após investimento total','Payback total meses','Payback capital próprio meses','Saldo investidor','VPL','Aporte além giro'],...state.items.map(p=>{const q=M.project(p,state.settings),v=scenarioValues()[state.settings.scenario];return [p.name,p.analysisMode,p.investmentStatus==='partial'?'PARCIAL - payback provisório':'Completo',M.scenarios[state.settings.scenario].label,n(v.revenue),n(v.margin),state.settings.horizon,n(q.total),n(q.equity),p.analysisMode==='margin'?n(p.advertisedMargin):'',n(q.stable.scenarioMargin),p.analysisMode==='margin'?p.royaltiesIncluded:'Apurados',n(q.stable.projectCash),n(q.totalProfit),n(q.projectEnding),q.projectPayback===null?'Não retorna no horizonte':n(q.projectPayback),q.payback===null?'Sem recuperação ou sem aporte':n(q.payback),n(q.ending),n(q.npv),n(q.additional)];})];
 download(flow?'franquia-lab-fluxo.csv':'franquia-lab-comparacao.csv','\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('CSV exportado.');
}

document.addEventListener('click',ev=>{
 const btn=ev.target.closest('button,a');if(!btn)return;
 if(btn.dataset.mode){current().analysisMode=btn.dataset.mode;save();return render();}
 if(btn.dataset.action==='reset-scenario'){const k=state.settings.scenario,s=M.scenarios[k];state.settings.scenarioValues={...scenarioValues(),[k]:{revenue:Math.round((s.factor-1)*100),margin:s.marginDelta}};save();return render();}
 if(btn.closest('.brand')){ev.preventDefault();return move('overview');}
 if(btn.dataset.view){ev.preventDefault();return move(btn.dataset.view);}
 if(btn.dataset.scenario){state.settings.scenario=btn.dataset.scenario;save();return render();}
 if(btn.dataset.edit){state.selected=btn.dataset.edit;return move('editor');}
 if(btn.dataset.network!==undefined){const n=networks[Number(btn.dataset.network)];return add({name:n.name,source:n.url,notes:`Referência pública consultada em 26/10/2026: ${n.value}. ${n.desc} Preencher os valores da proposta confirmada; os anúncios não foram importados para os cálculos.`});}
 if(btn.dataset.removeExtra!==undefined){current().extra.splice(Number(btn.dataset.removeExtra),1);save();return render();}
 const action=btn.dataset.action;
 if(action==='new')return add();
 if(action==='backup'){download('franquia-lab-backup.json',JSON.stringify(state,null,2),'application/json');return toast('Backup exportado com todas as premissas.');}
 if(action==='import')return document.getElementById('import-file').click();
 if(action==='print')return window.print();
 if(action==='csv')return exportCSV();
 if(action==='cash-csv')return exportCSV(true);
 if(action==='add-cost'){current().extra.push({name:'Novo custo',value:0,type:'fixed'});save();return render();}
 if(action==='duplicate'){const p=current();return add({...p,id:undefined,name:p.name+' (cópia)',example:false,extra:p.extra.map(x=>({...x})),checked:[...p.checked]});}
 if(action==='delete'){const p=current();return ask('Excluir esta franquia?',`A proposta “${p.name}” será removida deste navegador. Exporte um backup se quiser guardá-la.`,()=>{state.items=state.items.filter(x=>x.id!==p.id);state.selected=state.items[0]?.id;save();render();toast('Proposta excluída.');});}
 if(action==='remove-examples')return ask('Remover os exemplos fictícios?','As propostas criadas ou duplicadas por você serão preservadas.',()=>{state.items=state.items.filter(p=>!p.example);state.selected=state.items[0]?.id;save();render();});
 if(action==='examples'){if(state.items.length+3>30)return toast('Sem espaço para três exemplos.');state.items.push(...M.seeds().map(p=>({...p,id:crypto.randomUUID()})));state.selected=state.items[0].id;save();return render();}
});
document.addEventListener('change',ev=>{
 const el=ev.target;
 if(el.dataset.scenarioParam){if(!updateScenarioInput(el)){toast('Variação inválida: faturamento de −100% a +500%, margem de −100 a +100 p.p.');el.value=scenarioValues()[state.settings.scenario][el.dataset.scenarioParam];}return refreshNumericalResults();}
 if(el.id==='franchise-select'){state.selected=el.value;save();return render();}
 if(el.dataset.setting){let value=Number(el.value);const key=el.dataset.setting;const next={...state.settings,[key]:value};if(el.value===''||!validSettings(next)){el.value=state.settings[key];return toast('Informe um valor válido.');}state.settings=next;save();if(el.tagName==='SELECT')return render();return refreshNumericalResults();}
 if(el.dataset.check!==undefined){const p=current(),i=Number(el.dataset.check);p.checked=el.checked?[...new Set([...p.checked,i])]:p.checked.filter(x=>x!==i);return save();}
 if(el.dataset.extra!==undefined){const p=current(),i=Number(el.dataset.extra),prop=el.dataset.prop,old=p.extra[i][prop];const v=prop==='value'?Number(el.value):el.value;p.extra[i][prop]=v;if(M.validate(p).length||el.value===''){p.extra[i][prop]=old;el.value=old;return toast('Informe um custo válido.');}save();document.getElementById('live-summary').innerHTML=summary();return;}
 if(el.dataset.field){const p=current(),key=el.dataset.field,old=p[key];if(key==='investmentMode'&&el.value==='total'&&p.investmentTotal===0)p.investmentTotal=M.investment(p);p[key]=typeof M.defaults[key]==='number'?Number(el.value):el.value;if(M.validate(p).length||(typeof M.defaults[key]==='number'&&el.value==='')||(key==='name'&&!p.name.trim())){p[key]=old;el.value=old;return toast('Valor inválido. Confira os limites e o total financiado.');}save();if(['investmentStatus','contractMonths','analysisMode','investmentMode','royaltiesIncluded','revenueMode','royaltyMode'].includes(key))render();else document.getElementById('live-summary').innerHTML=summary();}
});
// Input also updates the model so navigation never discards an unblurred edit.
document.addEventListener('input',ev=>{
 const el=ev.target,p=current();
 if(el.dataset.scenarioParam)updateScenarioInput(el);
 if(el.dataset.setting&&el.tagName!=='SELECT'&&el.value!==''){
   const next={...state.settings,[el.dataset.setting]:Number(el.value)};
   if(validSettings(next)){state.settings=next;save();refreshNumericalResults();}
 }
 if(el.dataset.field&&p&&el.tagName!=='SELECT'){
   const key=el.dataset.field,old=p[key],numeric=typeof M.defaults[key]==='number';
   if(el.value===''&&numeric)return;
   p[key]=numeric?Number(el.value):el.value;
   if(M.validate(p).length||(key==='name'&&!p.name.trim())){p[key]=old;return;}
   save();const panel=document.getElementById('live-summary');if(panel){panel.innerHTML=summary();const installmentEl=document.getElementById("loan-installment");if(installmentEl)installmentEl.textContent=money(M.project(current(),state.settings).installment);}
   const loanInput=document.getElementById('field-loan');if(loanInput)loanInput.max=M.investment(p);
 }
 if(el.dataset.extra!==undefined&&p&&el.tagName!=='SELECT'){
   const i=Number(el.dataset.extra),key=el.dataset.prop,old=p.extra[i][key];
   if(key==='value'&&el.value==='')return;
   p.extra[i][key]=key==='value'?Number(el.value):el.value;
   if(M.validate(p).length){p.extra[i][key]=old;return;}
   save();const panel=document.getElementById('live-summary');if(panel){panel.innerHTML=summary();const installmentEl=document.getElementById("loan-installment");if(installmentEl)installmentEl.textContent=money(M.project(current(),state.settings).installment);}
 }
});

function updateScenarioInput(el){
 if(el.value==='')return false;
 const key=state.settings.scenario,param=el.dataset.scenarioParam;
 const scenarioValuesNext={...scenarioValues(),[key]:{...scenarioValues()[key],[param]:Number(el.value)}};
 const next={...state.settings,scenarioValues:scenarioValuesNext};
 if(!validSettings(next))return false;
 state.settings=next;save();refreshNumericalResults();return true;
}

document.addEventListener('focusout',ev=>{if((ev.target.dataset.setting||ev.target.dataset.scenarioParam)&&ev.target.tagName!=='SELECT')refreshNumericalResults();});
document.getElementById('import-file').addEventListener('change',async ev=>{const file=ev.target.files[0];ev.target.value='';if(!file)return;try{if(file.size>2000000)throw Error('Arquivo muito grande.');const next=parseStudy(JSON.parse(await file.text()));ask('Importar este estudo?',`O arquivo contém ${next.items.length} propostas e substituirá o estudo atual neste navegador.`,()=>{state=next;save();render();toast('Estudo importado.');});}catch(err){toast('Não foi possível importar: '+err.message);}});
render();
